local ServingTongsMaker = {}
local PRODUCTS = {
    iron_servingtongs = { name = "Železni servirne klešče", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni servirne klešče za kuharje." },
    bronze_servingtongs = { name = "Bronast servirne klešče", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast servirne klešče za kuharje." },
    silver_servingtongs = { name = "Srebrn servirne klešče", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn servirne klešče za kuharje." },
    gilded_servingtongs = { name = "Pozlačen servirne klešče", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen servirne klešče za kuharje." },
    jewel_set_servingtongs = { name = "Draguljast servirne klešče", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast servirne klešče za kuharje." },
    royal_sovereign_servingtongs = { name = "Kraljevski suveren servirne klešče", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren servirne klešče z biseri za krono." },
}
local BUILDINGS = {
    servingtongs_workshop = { name = "Servingtongs delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    servingtongs_house = { name = "Servingtongs hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_servingtongs_atelier = { name = "Mojstrski servingtongs atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_servingtongs_palace = { name = "Suverena servingtongs palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
ServingTongsMaker.ironStock=18; ServingTongsMaker.bronzeStock=14; ServingTongsMaker.woodStock=10; ServingTongsMaker.leatherStock=8; ServingTongsMaker.silverStock=8; ServingTongsMaker.goldStock=6; ServingTongsMaker.jewelStock=4; ServingTongsMaker.pearlStock=4
ServingTongsMaker.productStock = {}; ServingTongsMaker.buildings = {}; ServingTongsMaker.maker = nil; ServingTongsMaker.activeMaking = {}; ServingTongsMaker.totalProducts = 0; ServingTongsMaker.dayTimer = 0
function ServingTongsMaker.init() ServingTongsMaker.ironStock=18; ServingTongsMaker.bronzeStock=14; ServingTongsMaker.woodStock=10; ServingTongsMaker.leatherStock=8; ServingTongsMaker.silverStock=8; ServingTongsMaker.goldStock=6; ServingTongsMaker.jewelStock=4; ServingTongsMaker.pearlStock=4; ServingTongsMaker.productStock={}; ServingTongsMaker.buildings={}; ServingTongsMaker.maker=nil; ServingTongsMaker.activeMaking={}; ServingTongsMaker.totalProducts=0; ServingTongsMaker.dayTimer=0; print("[ServingTongsMaker] Royal Serving Tongs Maker System initialized (6 products, 4 buildings)") end
function ServingTongsMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ServingTongsMaker.maker={name=n or ("Kleščar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kleščar najet: %s (spretnost: %d)",ServingTongsMaker.maker.name,s),"success") end; return true end
function ServingTongsMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ServingTongsMaker.build(id) local ok,e=ServingTongsMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ServingTongsMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ServingTongsMaker.getQualityBonus() local b=0; for _,bd in ipairs(ServingTongsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ServingTongsMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ServingTongsMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ServingTongsMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ServingTongsMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ServingTongsMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ServingTongsMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ServingTongsMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ServingTongsMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ServingTongsMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ServingTongsMaker.buildings==0 then return false,"Potrebna kleščna delavnica" end; if not ServingTongsMaker.maker then return false,"Potreben kleščar" end; return true end
function ServingTongsMaker.make(pt,qty) qty=qty or 1; local ok,e=ServingTongsMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ServingTongsMaker.ironStock=ServingTongsMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ServingTongsMaker.bronzeStock=ServingTongsMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ServingTongsMaker.woodStock=ServingTongsMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ServingTongsMaker.leatherStock=ServingTongsMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ServingTongsMaker.silverStock=ServingTongsMaker.silverStock-d.silverCost*qty end; if d.goldCost then ServingTongsMaker.goldStock=ServingTongsMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ServingTongsMaker.jewelStock=ServingTongsMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ServingTongsMaker.pearlStock=ServingTongsMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ServingTongsMaker.maker then t=math.max(1,t-math.floor(ServingTongsMaker.maker.skill/13)) end; table.insert(ServingTongsMaker.activeMaking,{id="servingtongs_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ServingTongsMaker.completeMaking(m) local q=1.0+(ServingTongsMaker.getQualityBonus()/100); if ServingTongsMaker.maker then q=q+(ServingTongsMaker.maker.skill/140) end; q=math.min(2.5,q); ServingTongsMaker.productStock[m.productType]=(ServingTongsMaker.productStock[m.productType] or 0)+m.quantity; ServingTongsMaker.totalProducts=ServingTongsMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ServingTongsMaker.maker then ServingTongsMaker.maker.itemsMade=ServingTongsMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ServingTongsMaker.maker.skill=math.min(100,ServingTongsMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klešče izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"servingtongs.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ServingTongsMaker.update(dt) if not _G.state then return end; ServingTongsMaker.dayTimer=ServingTongsMaker.dayTimer+dt; if ServingTongsMaker.dayTimer>=30 then ServingTongsMaker.dayTimer=0; for i=#ServingTongsMaker.activeMaking,1,-1 do local m=ServingTongsMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ServingTongsMaker.completeMaking(m); table.remove(ServingTongsMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ServingTongsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ServingTongsMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ServingTongsMaker.getStats() return {ironStock=ServingTongsMaker.ironStock,bronzeStock=ServingTongsMaker.bronzeStock,woodStock=ServingTongsMaker.woodStock,leatherStock=ServingTongsMaker.leatherStock,silverStock=ServingTongsMaker.silverStock,goldStock=ServingTongsMaker.goldStock,jewelStock=ServingTongsMaker.jewelStock,pearlStock=ServingTongsMaker.pearlStock,productStock=ServingTongsMaker.productStock,numBuildings=#ServingTongsMaker.buildings,hasMaker=ServingTongsMaker.maker~=nil,makerName=ServingTongsMaker.maker and ServingTongsMaker.maker.name or "—",makerSkill=ServingTongsMaker.maker and ServingTongsMaker.maker.skill or 0,activeMaking=#ServingTongsMaker.activeMaking,totalProducts=ServingTongsMaker.totalProducts} end
return ServingTongsMaker
